import itertools

def solve_2x2():
    min_paths = float('inf')
    for p in itertools.permutations(range(1, 5)):
        board = [[p[0], p[1]], [p[2], p[3]]]

        def get_neighbors(r, c):
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 2 and 0 <= nc < 2:
                    yield nr, nc

        # Local minima
        L = []
        for r in range(2):
            for c in range(2):
                is_min = True
                for nr, nc in get_neighbors(r, c):
                    if board[nr][nc] < board[r][c]:
                        is_min = False
                        break
                if is_min:
                    L.append((r, c))

        # dp[r][c] = number of increasing paths starting at (r, c)
        # Since it's a DAG, we can use memoization or compute in reverse order of values
        dp = [[0]*2 for _ in range(2)]
        cells = []
        for r in range(2):
            for c in range(2):
                cells.append((board[r][c], r, c))
        cells.sort(reverse=True)

        for val, r, c in cells:
            count = 1
            for nr, nc in get_neighbors(r, c):
                if board[nr][nc] > board[r][c]:
                    count += dp[nr][nc]
            dp[r][c] = count

        total_paths = sum(dp[r][c] for r, c in L)
        min_paths = min(min_paths, total_paths)
    return min_paths

