def solve_nxn_simulated_annealing(n):
    # Start with a random permutation
    p = list(range(1, n*n + 1))
    random.shuffle(p)

    def get_board(p):
        return [p[i*n:(i+1)*n] for i in range(n)]

    current_board = get_board(p)
    current_paths = get_paths(current_board, n)
    min_paths = current_paths

    T = 1.0
    T_min = 0.01
    alpha = 0.99

    for i in range(10000):
        # Try swapping two elements
        idx1 = random.randint(0, n*n - 1)
        idx2 = random.randint(0, n*n - 1)
        p[idx1], p[idx2] = p[idx2], p[idx1]

        new_board = get_board(p)
        new_paths = get_paths(new_board, n)

        if new_paths < current_paths or random.random() < 2.718**((current_paths - new_paths)/T):
            current_paths = new_paths
            if current_paths < min_paths:
                min_paths = current_paths
        else:
            p[idx1], p[idx2] = p[idx2], p[idx1]

        T *= alpha
        if T < T_min:
            T = 1.0

    return min_paths

